INSERT INTO public.questions (category_id, content, options, answer, explanation)
VALUES 
  ('c1000000-1111-1111-1111-000000000001', 'オンプレミスからクラウドへ移行する主な経済的メリットはどれですか？', '["CapExからOpExへの移行", "ハードウェア資産の最大化", "IT部門の固定資産化", "減価償却期間の短縮"]'::jsonb, 'CapExからOpExへの移行', '初期投資（CapEx）を運用費用（OpEx）に変換できます。'),
  ('c1000000-1111-1111-1111-000000000001', 'クラウドの「敏捷性」とは何を指しますか？', '["レガシー維持", "ネットワーク速度の固定", "サーバー移動能力", "迅速なプロビジョニング"]'::jsonb, '迅速なプロビジョニング', '数分でリソースを確保し市場に対応できる能力です。'),
  ('c1000000-1111-1111-1111-000000000001', 'スケーラビリティの正しい説明はどれですか？', '["一定CPUの提供", "物理的分離", "リージョン限定", "需要に応じたリソース調整"]'::jsonb, '需要に応じたリソース調整', '需要の増減に応じてリソースを自動的または手動で調整できる能力です。'),
  ('c1000000-1111-1111-1111-000000000001', 'ハイブリッドクラウドの定義は？', '["プライベートのみ", "複数クラウドの併用", "オンプレミスとクラウドの組み合わせ", "エッジコンピューティング"]'::jsonb, 'オンプレミスとクラウドの組み合わせ', '自社所有環境とパブリッククラウドを組み合わせた構成です。'),
  ('c1000000-1111-1111-1111-000000000001', 'TCO (Total Cost of Ownership) 削減に含まれないものは？', '["維持費削減", "ハード更新費削減", "クラウド利用料", "人件費削減"]'::jsonb, 'クラウド利用料', 'クラウド利用料は新たなコストですが、全体の保有コストは削減されます。'),
  ('c1000000-1111-1111-1111-000000000001', 'SaaSの例として正しいものは？', '["BigQuery", "Google Workspace", "Cloud Functions", "Compute Engine"]'::jsonb, 'Google Workspace', 'ソフトウェアをサービスとして利用する形態です。'),
  ('c1000000-1111-1111-1111-000000000001', 'PaaSの主要なメリットはどれですか？', '["OS管理の自由度", "物理ハードの直接操作", "インフラ管理なしの開発集中", "最安のストレージコスト"]'::jsonb, 'インフラ管理なしの開発集中', 'プラットフォームをサービスとして提供し、開発者がコードに集中できるようにします。'),
  ('c1000000-1111-1111-1111-000000000001', 'IaaSの説明として適切なものは？', '["DBのみを提供", "仮想的な基盤リソースを提供", "アプリのみを提供", "メール機能を提供"]'::jsonb, '仮想的な基盤リソースを提供', 'サーバー、ネットワーク、ストレージなどのインフラを提供します。'),
  ('c1000000-1111-1111-1111-000000000001', 'クラウドネイティブな文化において重要な考え方は？', '["小規模な失敗を許容し迅速に改善する", "失敗を避ける厳格な管理", "個人の責任追及", "ドキュメント重視の長期開発"]'::jsonb, '小規模な失敗を許容し迅速に改善する', '心理的安全性と迅速なイテレーションが重要です。'),
  ('c1000000-1111-1111-1111-000000000001', 'マルチクラウド戦略の主な動機はどれですか？', '["管理の簡素化", "コストの一元化", "ベンダーロックインの回避", "単一障害点の作成"]'::jsonb, 'ベンダーロックインの回避', '複数のクラウドを使い分けることで、特定のベンダーへの依存を減らします。'),
  ('c1000000-1111-1111-1111-000000000001', 'デジタルトランスフォーメーション (DX) の真の意味は？', '["最新PCを導入すること", "ビジネスモデルをテクノロジーで革新すること", "IT部門の人数を増やすこと", "紙をPDFにすること"]'::jsonb, 'ビジネスモデルをテクノロジーで革新すること', '単なるデジタル化（デジタイゼーション）ではなく、変革（トランスフォーメーション）を指します。'),
  ('c1000000-1111-1111-1111-000000000001', 'Google Cloud が推進する「データ民主化」とは？', '["全データを公開すること", "全員がデータを消せること", "必要な人が必要な時にデータにアクセス・分析できること", "データ管理を外部に委託すること"]'::jsonb, '必要な人が必要な時にデータにアクセス・分析できること', '専門家だけでなく、ビジネスユーザーもデータを活用できる環境を目指します。'),
  ('c1000000-1111-1111-1111-000000000001', 'リージョン (Region) の定義は？', '["1つのラック", "全世界のネットワーク", "特定の地理的な領域", "単一のデータセンター"]'::jsonb, '特定の地理的な領域', '東京やアイオワなど、地理的に分けられたエリアです。'),
  ('c1000000-1111-1111-1111-000000000001', 'ゾーン (Zone) の説明として正しいものは？', '["1つのIPアドレス", "大陸全体の区分", "リージョン内の独立した障害ドメイン", "仮想的なユーザーグループ"]'::jsonb, 'リージョン内の独立した障害ドメイン', 'リージョン内に複数あり、物理的に独立したインフラを持ちます。'),
  ('c1000000-1111-1111-1111-000000000001', '「高可用性 (High Availability)」を達成するための一般的な手法は？', '["複数のゾーンやリージョンに分散配置", "バックアップを同じサーバーに置く", "CPU使用率を常に100%にする", "単一のゾーンで運用"]'::jsonb, '複数のゾーンやリージョンに分散配置', '障害発生時もサービスを継続できるよう冗長化します。'),
  ('c1000000-1111-1111-1111-000000000001', 'API (Application Programming Interface) の役割は？', '["ハードウェアの修理", "パスワードの記憶", "データの物理的な削除", "異なるソフトウェア間の通信と連携"]'::jsonb, '異なるソフトウェア間の通信と連携', 'サービス間のデータ交換や機能を呼び出すための窓口です。'),
  ('c1000000-1111-1111-1111-000000000001', '「フォールト トレランス (Fault Tolerance)」とは？', '["障害を予知する能力", "ネットワークを高速化する能力", "障害が起きても中断せず動作し続ける能力", "障害時に全停止する能力"]'::jsonb, '障害が起きても中断せず動作し続ける能力', '冗長性などにより、コンポーネントの故障を許容します。'),
  ('c1000000-1111-1111-1111-000000000001', 'クラウド移行における「リフト＆シフト」とは？', '["アプリを全面的に書き直して移行", "既存の構成をほぼ変えずにクラウドへ移行", "データをすべて消去して新規作成", "移行を諦めてオンプレに留まる"]'::jsonb, '既存の構成をほぼ変えずにクラウドへ移行', 'Rehostingとも呼ばれ、迅速な移行が可能です。'),
  ('c1000000-1111-1111-1111-000000000001', '「エラスティシティ (Elasticity)」の説明は？', '["データが消えないこと", "セキュリティが強化されること", "価格が固定されること", "需要に合わせてリソースが伸縮すること"]'::jsonb, '需要に合わせてリソースが伸縮すること', '負荷に応じて自動的にリソースを増減させる特性です。'),
  ('c1000000-1111-1111-1111-000000000001', 'Google Cloud が環境負荷低減のために行っていることは？', '["サーバーの冷却を止める", "古い機器を使い続ける", "カーボンニュートラルな運営と再エネ購入", "紙の資料を増やす"]'::jsonb, 'カーボンニュートラルな運営と再エネ購入', '持続可能なクラウド運営を推進しています。'),
  ('c1000000-1111-1111-1111-000000000001', '移行戦略の「Replatforming」とは？', '["アプリのコードは変えず、DBなどをマネージドサービスに置き換える", "SaaSに乗り換える", "物理サーバーをそのまま運ぶ", "アプリを最初から作り直す"]'::jsonb, 'アプリのコードは変えず、DBなどをマネージドサービスに置き換える', '「リフト＆シェイプ」とも呼ばれ、クラウドの恩恵を部分的に享受します。'),
  ('c1000000-1111-1111-1111-000000000001', '「Refactoring」が推奨されるケースは？', '["一刻も早く移行を完了したい場合", "アプリを廃棄する場合", "パッケージソフトをそのまま使いたい場合", "既存アプリの機能をクラウドネイティブな機能で再構築したい場合"]'::jsonb, '既存アプリの機能をクラウドネイティブな機能で再構築したい場合', '最もクラウドの恩恵を受けられますが、工数もかかります。'),
  ('c1000000-1111-1111-1111-000000000001', '移行戦略の「Retire」とは？', '["移行を延期する", "別のクラウドに移行する", "不要になったアプリケーションを廃止する", "アプリを最新版に更新する"]'::jsonb, '不要になったアプリケーションを廃止する', '不要な資産を整理し、コストを削減します。'),
  ('c1000000-1111-1111-1111-000000000001', 'クラウド環境における「スケーリング・アウト」とは？', '["インスタンスの数を増やす", "インスタンスのスペックを上げる", "ネットワークを広げる", "データを削除する"]'::jsonb, 'インスタンスの数を増やす', '水平スケーリングとも呼ばれ、柔軟な対応が可能です。'),
  ('c1000000-1111-1111-1111-000000000001', 'クラウド環境における「スケーリング・アップ」とは？', '["物理サーバーを追加する", "利用時間を増やす", "インスタンスのスペックを上げる", "インスタンスの数を増やす"]'::jsonb, 'インスタンスのスペックを上げる', '垂直スケーリングとも呼ばれます。'),
  ('c1000000-1111-1111-1111-000000000001', '企業内に設置する「CCoE (Cloud Center of Excellence)」の役割は？', '["組織全体のクラウド活用を推進し、ガバナンスや標準化を担う", "クラウドの料金を支払うだけの部署", "社員のPCを管理する", "全サーバーを一人で修理する"]'::jsonb, '組織全体のクラウド活用を推進し、ガバナンスや標準化を担う', '組織的なクラウド導入に不可欠な専門組織です。'),
  ('c1000000-1111-1111-1111-000000000001', 'データドリブンな組織への変革に必要なことは？', '["直感に頼らずデータに基づいて意思決定を行う文化", "IT部門にすべてを任せきりにすること", "データをすべて隠すこと", "AIを導入するだけで満足すること"]'::jsonb, '直感に頼らずデータに基づいて意思決定を行う文化', '技術だけでなく文化の変革が重要です。'),
  ('c1000000-1111-1111-1111-000000000001', '「耐久性 (Durability)」とは何の指標ですか？', '["データが失われない確率", "ネットワークの速度", "システムが稼働している時間", "サーバーの起動時間"]'::jsonb, 'データが失われない確率', 'ストレージなどで99.999999999%のように表現されます。'),
  ('c1000000-1111-1111-1111-000000000001', '「信頼性 (Reliability)」の定義は？', '["データが絶対に盗まれないこと", "サーバーが最新であること", "料金が安いこと", "意図した期間、正常に動作し続ける能力"]'::jsonb, '意図した期間、正常に動作し続ける能力', '可用性を含む広い概念です。'),
  ('c1000000-1111-1111-1111-000000000001', 'クラウド移行の「Repurchasing」とは？', '["ライセンスを更新する", "中古のハードウェアを買う", "既存アプリを捨てて、同等の機能を持つSaaSへ乗り換える", "同じサーバーを買い直す"]'::jsonb, '既存アプリを捨てて、同等の機能を持つSaaSへ乗り換える', 'CRMを自社開発からSaaSに変えるなどの例があります。'),
  ('c1000000-1111-1111-1111-000000000001', '移行戦略の「Retain」とは？', '["今のところは移行せずオンプレミスに残す", "アプリを新しく作り直す", "データをすべて削除する", "移行を強制的に進める"]'::jsonb, '今のところは移行せずオンプレミスに残す', '依存関係やコストの関係で、すぐには移行しない選択です。'),
  ('c1000000-1111-1111-1111-000000000001', 'クラウドにおける「マネージド サービス」を利用する最大の利点は？', '["インターネットが不要になる", "運用・管理の負担をベンダーに任せ、ビジネス価値に集中できる", "中身をすべて自由にカスタマイズできる", "料金が必ず安くなる"]'::jsonb, '運用・管理の負担をベンダーに任せ、ビジネス価値に集中できる', 'サーバーレスなどはその究極の形です。'),
  ('c1000000-1111-1111-1111-000000000001', '「サーバーレス」コンピューティングの誤った説明はどれですか？', '["リソースが自動的にスケールする", "使用した分だけ料金が発生する", "ユーザーがサーバーの管理・構築を意識しなくてよい", "物理的なサーバーが全く存在しない"]'::jsonb, '物理的なサーバーが全く存在しない', 'サーバーは存在しますが、クラウドベンダーが管理しています。'),
  ('c1000000-1111-1111-1111-000000000001', '「マイクロサービス アーキテクチャ」のメリットは？', '["各サービスを独立して開発・デプロイでき、変更に強い", "システム全体が一枚岩で管理しやすい", "開発コストが常に最小になる", "通信速度が必ず速くなる"]'::jsonb, '各サービスを独立して開発・デプロイでき、変更に強い', 'スケーラビリティとアジリティが向上します。'),
  ('c1000000-1111-1111-1111-000000000001', '「デプロイメント (Deployment)」とは？', '["開発したコードを本番環境などで動かせる状態にすること", "コードを削除すること", "仕様書を書くこと", "PCをセットアップすること"]'::jsonb, '開発したコードを本番環境などで動かせる状態にすること', '迅速なデプロイはビジネスのアジリティを高めます。'),
  ('c1000000-1111-1111-1111-000000000001', '「イミュータブル インフラストラクチャ」とは？', '["パスワードを変えない", "バックアップを取らない", "サーバーの場所を固定する", "一度構築したサーバーに変更を加えず、更新時は新しく作り直す"]'::jsonb, '一度構築したサーバーに変更を加えず、更新時は新しく作り直す', '環境の不整合を防ぐ手法です。'),
  ('c1000000-1111-1111-1111-000000000001', 'クラウドの「グローバル フットプリント」が企業に提供する価値は？', '["世界中に支店を出せる", "料金が全世界で一律になる", "世界中のユーザーの近くで低遅延なサービスを提供できる", "翻訳が自動で行われる"]'::jsonb, '世界中のユーザーの近くで低遅延なサービスを提供できる', 'Googleの広大なネットワークインフラを活用できます。'),
  ('c1000000-1111-1111-1111-000000000001', '企業のクラウド導入フェーズにおいて、最初に検討すべきことは？', '["ビジネス目標とクラウドで解決したい課題の明確化", "一番安いプランを探すこと", "プログラミング言語を決めること", "サーバーを何台買うか決めること"]'::jsonb, 'ビジネス目標とクラウドで解決したい課題の明確化', '目的が不明確な移行は失敗の原因になります。'),
  ('c1000000-1111-1111-1111-000000000001', '「ハイパースケール クラウド」とは？', '["手動で管理するクラウド", "非常に小さなクラウド", "膨大な計算リソースを必要に応じて瞬時に提供できる大規模なクラウド", "速度が遅いクラウド"]'::jsonb, '膨大な計算リソースを必要に応じて瞬時に提供できる大規模なクラウド', 'Google Cloudのような大規模ベンダーを指します。'),
  ('c1000000-1111-1111-1111-000000000001', 'データ活用において「サイロ化」が問題になる理由は？', '["データが増えすぎること", "データの形式が統一されること", "データが部門ごとに分断され、組織全体での活用が妨げられる", "データが公開されること"]'::jsonb, 'データが部門ごとに分断され、組織全体での活用が妨げられる', '横断的な分析やインサイトの獲得が難しくなります。');
INSERT INTO public.questions (category_id, content, options, answer, explanation)
VALUES 
  ('c2000000-2222-2222-2222-000000000002', '非構造化データを安価に大量保存するサービスは？', '["BigQuery", "Cloud SQL", "Cloud Storage", "Cloud Spanner"]'::jsonb, 'Cloud Storage', '画像やログなどのオブジェクトストレージです。'),
  ('c2000000-2222-2222-2222-000000000002', 'リレーショナルDBでグローバルスケーリングが可能なのは？', '["Cloud Spanner", "Bigtable", "Firestore", "Cloud SQL"]'::jsonb, 'Cloud Spanner', '強整合性と水平スケーリングを両立します。'),
  ('c2000000-2222-2222-2222-000000000002', 'SQLで高速分析が可能なサーバーレスDWHは？', '["BigQuery", "Dataproc", "Dataflow", "Pub/Sub"]'::jsonb, 'BigQuery', '管理不要で大規模分析が可能です。'),
  ('c2000000-2222-2222-2222-000000000002', 'リアルタイムメッセージングサービスは？', '["Cloud Run", "Pub/Sub", "App Engine", "Dataflow"]'::jsonb, 'Pub/Sub', '非同期なメッセージ配信を管理します。'),
  ('c2000000-2222-2222-2222-000000000002', 'データ可視化と探索を行うプラットフォームは？', '["BigQuery ML", "Data Catalog", "Vertex AI", "Looker"]'::jsonb, 'Looker', 'モダンなBIツールです。'),
  ('c2000000-2222-2222-2222-000000000002', '大量の書き込みを低遅延で処理するNoSQLは？', '["Cloud SQL", "Cloud Spanner", "Cloud Bigtable", "Firestore"]'::jsonb, 'Cloud Bigtable', 'IoTや金融データなどに適しています。'),
  ('c2000000-2222-2222-2222-000000000002', 'フルマネージドのMySQL/PostgreSQLサービスは？', '["Cloud SQL", "Memorystore", "AlloyDB", "BigQuery"]'::jsonb, 'Cloud SQL', '標準的なリレーショナルDBを提供します。'),
  ('c2000000-2222-2222-2222-000000000002', 'モバイル/Webアプリ向けのNoSQLドキュメントDBは？', '["BigQuery", "Bigtable", "Cloud SQL", "Firestore"]'::jsonb, 'Firestore', 'リアルタイム同期が可能なDBです。'),
  ('c2000000-2222-2222-2222-000000000002', 'バッチとストリームの両方を処理するデータパイプラインは？', '["Pub/Sub", "Dataproc", "Cloud Build", "Dataflow"]'::jsonb, 'Dataflow', 'Apache Beamベースの処理エンジンです。'),
  ('c2000000-2222-2222-2222-000000000002', 'Hadoop/Sparkのマネージドサービスは？', '["Dataflow", "Dataproc", "BigQuery", "Cloud Run"]'::jsonb, 'Dataproc', '既存のOSSビッグデータツールをクラウドで動かします。'),
  ('c2000000-2222-2222-2222-000000000002', 'データガバナンスと検索のためのメタデータ管理ツールは？', '["Dataplex", "Cloud Storage", "AlloyDB", "BigQuery"]'::jsonb, 'Dataplex', '統合されたデータ管理プラットフォームです。'),
  ('c2000000-2222-2222-2222-000000000002', 'PostgreSQL互換の高性能なエンタープライズDBは？', '["AlloyDB", "Cloud Spanner", "Cloud SQL", "Firestore"]'::jsonb, 'AlloyDB', '高い可用性とパフォーマンスを提供します。'),
  ('c2000000-2222-2222-2222-000000000002', 'インメモリのRedis/Memcachedサービスは？', '["Cloud SQL", "BigQuery", "AlloyDB", "Memorystore"]'::jsonb, 'Memorystore', '高速なキャッシュ機能を提供します。'),
  ('c2000000-2222-2222-2222-000000000002', '外部DBからBigQueryへリアルタイムにデータを複製するサービスは？', '["Datastream", "Dataflow", "Cloud Storage", "Pub/Sub"]'::jsonb, 'Datastream', 'CDCサービスです。'),
  ('c2000000-2222-2222-2222-000000000002', 'BigQueryで外部のデータを分析する機能は？', '["BigQuery Omni", "BigQuery Studio", "BigQuery ML", "BigLake"]'::jsonb, 'BigQuery Omni', 'マルチクラウド分析を可能にします。'),
  ('c2000000-2222-2222-2222-000000000002', 'データレイクとDWHの境界をなくし、共通のガバナンスを適用するストレージエンジンは？', '["Dataplex", "BigQuery", "BigLake", "Cloud Storage"]'::jsonb, 'BigLake', 'データの場所を問わず一貫した管理を可能にします。'),
