  ('c3000000-3333-3333-3333-000000000003', '「オーケストレーション」とは何を指しますか？', '["多数のコンテナの配備、管理、スケーリングを自動化すること", "コードを書くこと", "音楽を流すこと", "サーバーを修理すること"]'::jsonb, '多数 of コンテナの配備、管理、スケーリングを自動化すること', 'Kubernetesはその代表的なツールです。'),
  ('c3000000-3333-3333-3333-000000000003', 'Cloud Functions が適しているのは？', '["短時間で終わる単一の処理（イベントへの応答）", "動画のリアルタイム編集", "大規模なデータベース管理", "24時間稼働の巨大なシステム"]'::jsonb, '短時間で終わる単一の処理（イベントへの応答）', 'ファイルのアップロードやHTTPリクエストなどをトリガーに動作します。'),
  ('c3000000-3333-3333-3333-000000000003', 'App Engine の「スタンダード環境」の特徴は？', '["特定の言語向けに最適化され、ゼロから自動スケールする", "何でもインストールできる", "料金が非常に高い", "OSの設定が必要"]'::jsonb, '特定の言語向けに最適化され、ゼロから自動スケールする', 'リクエストがない時は0インスタンスまで縮小し、コストを抑えます。'),
  ('c3000000-3333-3333-3333-000000000003', 'App Engine の「フレキシブル環境」の特徴は？', '["OSの管理が必要", "言語が限定される", "自動スケールしない", "Dockerコンテナを使用して自由なランタイムを実行できる"]'::jsonb, 'Dockerコンテナを使用して自由なランタイムを実行できる', 'より自由度が必要なWebアプリに適しています。'),
  ('c3000000-3333-3333-3333-000000000003', 'VPC の「サブネット」とは？', '["1つのサーバー", "全世界共通のネットワーク", "リージョン内のIPアドレス範囲の区分", "ユーザーの名前"]'::jsonb, 'リージョン内のIPアドレス範囲の区分', 'ネットワークを論理的に分割して管理します。'),
  ('c3000000-3333-3333-3333-000000000003', '「Shared VPC」の利点は？', '["料金を2倍にする", "管理者を一人にする", "ネットワークを遮断する", "複数のプロジェクトで共通のVPCネットワークを共有・一元管理できる"]'::jsonb, '複数のプロジェクトで共通のVPCネットワークを共有・一元管理できる', '組織全体で一貫したネットワークポリシーを適用できます。'),
  ('c3000000-3333-3333-3333-000000000003', '「VPC ネットワーク ペアリング」とは？', '["異なるVPCネットワーク同士を内部IPで直接接続すること", "インターネットに公開すること", "VPNを張ること", "VPCを削除すること"]'::jsonb, '異なるVPCネットワーク同士を内部IPで直接接続すること', '低遅延でセキュアな通信を可能にします。'),
  ('c3000000-3333-3333-3333-000000000003', 'Cloud Load Balancing の「エニーキャスト IP」のメリットは？', '["料金が無料になる", "IPが毎日変わる", "アクセスが遅くなる", "世界中どこからでも1つのIPアドレスでアクセスでき、最寄りの拠点に誘導される"]'::jsonb, '世界中どこからでも1つのIPアドレスでアクセスでき、最寄りの拠点に誘導される', 'ユーザー体験の向上と管理の簡素化を実現します。'),
  ('c3000000-3333-3333-3333-000000000003', '「Cloud DNS」の役割は？', '["ドメイン名とIPアドレスを変換するマネージドサービス", "データを保存する", "サーバーを監視する", "メールを送る"]'::jsonb, 'ドメイン名とIPアドレスを変換するマネージドサービス', '高い可用性を持つ権威DNSサービスです。'),
  ('c3000000-3333-3333-3333-000000000003', '「Cloud CDN」の目的は？', '["Googleのネットワークの端（エッジ）でコンテンツをキャッシュし配信を高速化する", "課金を止める", "プログラムをビルドする", "データを削除する"]'::jsonb, 'Googleのネットワークの端（エッジ）でコンテンツをキャッシュし配信を高速化する', '静的コンテンツの低遅延配信に有効です。'),
  ('c3000000-3333-3333-3333-000000000003', '「Infrastructure as Code (IaC)」の考え方は？', '["手動でサーバーを作る", "インフラの構成をコード（設定ファイル）で管理し、自動化・再現可能にする", "インフラを捨ててコードだけにする", "紙に構成を書く"]'::jsonb, 'インフラの構成をコードで管理し、自動化・再現可能にする', 'TerraformやDeployment Managerなどで実現します。'),
  ('c3000000-3333-3333-3333-000000000003', '「マネージド インスタンス グループ (MIG)」の利点は？', '["VMを1台ずつ手動で管理する", "同じ構成のVMを自動的に修復、スケーリング、更新できる", "VMの速度を下げる", "VMを削除する"]'::jsonb, '同じ構成のVMを自動的に修復、スケーリング、更新できる', '高可用性と運用の自動化に不可欠です。'),
  ('c3000000-3333-3333-3333-000000000003', '「Cloud Run Jobs」が適しているのは？', '["データベース", "Webサイトのホスティング", "リクエストへの応答ではなく、一回限りのタスクやバッチ処理", "チャットアプリ"]'::jsonb, 'リクエストへの応答ではなく、一回限りのタスクやバッチ処理', 'データ処理やスクリプトの実行に適したサーバーレス環境です。'),
  ('c3000000-3333-3333-3333-000000000003', 'Google Cloud の「リソース管理階層」の正しい順序は？', '["組織 > フォルダ > プロジェクト > リソース", "組織 > プロジェクト > リソース", "リソース > プロジェクト > 組織", "プロジェクト > フォルダ > 組織 > リソース"]'::jsonb, '組織 > フォルダ > プロジェクト > リソース', '権限継承やコスト管理の基盤となる構造です。'),
  ('c3000000-3333-3333-3333-000000000003', '「Google Cloud コンソール」とは？', '["スマホのアプリ", "コマンドを入力する黒い画面", "ブラウザからリソースを管理・操作できるWebインターフェース", "ハードウェアのボタン"]'::jsonb, 'ブラウザからリソースを管理・操作できるWebインターフェース', '直感的にクラウド操作が可能です。'),
  ('c3000000-3333-3333-3333-000000000003', '「Cloud Shell」の利点は？', '["PCを買い換える必要がある", "オフラインで動作する", "料金が非常に高い", "ブラウザ上で、設定済みの管理ツールが含まれた一時的な開発環境を使える"]'::jsonb, 'ブラウザ上で、設定済みの管理ツールが含まれた一時的な開発環境を使える', '追加料金なしで、どこからでも管理コマンドを実行できます。'),
  ('c3000000-3333-3333-3333-000000000003', '「リソース階層」において、フォルダを使用する主な目的は？', '["部門や環境（本番・テスト等）ごとにプロジェクトをグループ化し、権限を管理する", "速度を上げる", "ファイルを保存する", "ログを削除する"]'::jsonb, '部門や環境ごとにプロジェクトをグループ化し、権限を管理する', '組織的な管理を容易にします。');
INSERT INTO public.questions (category_id, content, options, answer, explanation)
VALUES 
  ('c4000000-4444-4444-4444-000000000004', '専門知識なしでカスタムモデルを構築する機能は？', '["Vertex AI", "TensorFlow", "PyTorch", "AutoML"]'::jsonb, 'AutoML', 'GUIベースでMLモデルを構築できます。'),
  ('c4000000-4444-4444-4444-000000000004', '統合AIプラットフォームでMLOpsをサポートするのは？', '["Looker", "Vertex AI", "Vision API", "BigQuery ML"]'::jsonb, 'Vertex AI', '全AIツールを統合した環境です。'),
  ('c4000000-4444-4444-4444-000000000004', '画像分析用トレーニング済みAPIは？', '["Cloud Vision API", "Speech-to-Text API", "Translation API", "Natural Language API"]'::jsonb, 'Cloud Vision API', '物体検出や文字認識などが可能です。'),
  ('c4000000-4444-4444-4444-000000000004', 'SQLだけでMLモデルを作成できる機能は？', '["BigQuery ML", "AutoML Video", "Vertex AI", "Dialogflow"]'::jsonb, 'BigQuery ML', 'データを動かさずに分析と予測が可能です。'),
  ('c4000000-4444-4444-4444-000000000004', '会話型AI（チャットボット）構築サービスは？', '["Contact Center AI", "Recommendations AI", "Dialogflow", "Vertex AI Search"]'::jsonb, 'Dialogflow', '自然な対話を実現するツールです。'),
  ('c4000000-4444-4444-4444-000000000004', '非構造化ドキュメントを解析するAIは？', '["Vision API", "Natural Language API", "Document AI", "Speech-to-Text API"]'::jsonb, 'Document AI', '請求書などのデータ抽出に特化しています。'),
  ('c4000000-4444-4444-4444-000000000004', '音声をテキストに変換するAPIは？', '["Text-to-Speech", "Cloud Speech-to-Text", "Natural Language API", "Translation API"]'::jsonb, 'Cloud Speech-to-Text', '文字起こしが可能です。'),
  ('c4000000-4444-4444-4444-000000000004', 'テキストの感情分析や構文解析を行うのは？', '["Video AI", "Translation API", "Vision API", "Natural Language API"]'::jsonb, 'Natural Language API', '文章の意味内容を理解するためのAPIです。'),
  ('c4000000-4444-4444-4444-000000000004', '動画内のシーン変化や物体を検出するのは？', '["Natural Language API", "Speech-to-Text API", "Video AI", "Vision API"]'::jsonb, 'Video AI', '動画コンテンツのメタデータ作成に有効です。'),
  ('c4000000-4444-4444-4444-000000000004', 'Vertex AIで提供される生成AIモデルのハブは？', '["Model Garden", "BigQuery", "AutoML", "AI Hub"]'::jsonb, 'Model Garden', '基盤モデルから選択・調整が可能です。'),
  ('c4000000-4444-4444-4444-000000000004', 'Googleの高性能なマルチモーダル生成AIモデルは？', '["BERT", "Gemini", "PaLM", "GPT"]'::jsonb, 'Gemini', 'テキスト、画像、音声を統合的に扱えます。'),
  ('c4000000-4444-4444-4444-000000000004', 'コード生成やトラブルシューティングを支援するAIアシスタントは？', '["BigQuery Studio", "Gemini for Google Cloud", "Vertex AI", "Cloud Build"]'::jsonb, 'Gemini for Google Cloud', '開発や運用の効率を向上させます。'),
  ('c4000000-4444-4444-4444-000000000004', '自社のデータを活用して生成AIエージェントを構築するツールは？', '["AutoML Search", "Vertex AI Agent Builder", "Dialogflow CX", "Contact Center AI"]'::jsonb, 'Vertex AI Agent Builder', '検索やチャット機能を自社データに特化させます。'),
  ('c4000000-4444-4444-4444-000000000004', 'ECサイト向けにパーソナライズされた商品を推奨するのは？', '["Recommendations AI", "Vision API", "BigQuery ML", "Looker"]'::jsonb, 'Recommendations AI', 'レコメンドを生成します。'),
  ('c4000000-4444-4444-4444-000000000004', 'MLモデルのパフォーマンスを監視しドリフトを検知するのは？', '["Error Reporting", "Cloud Monitoring", "Vertex AI Model Monitoring", "Cloud Trace"]'::jsonb, 'Vertex AI Model Monitoring', '予測精度の低下などを検知します。'),
  ('c4000000-4444-4444-4444-000000000004', 'AIの予測理由を可視化する機能は？', '["AutoML Vision", "Explainable AI", "Vertex AI Search", "Translation API"]'::jsonb, 'Explainable AI', 'AIの判断プロセスの透明性を高めます。'),
  ('c4000000-4444-4444-4444-000000000004', '機械学習に特化したGoogle設計のハードウェアは？', '["CPU", "TPU", "GPU", "ASIC"]'::jsonb, 'TPU', '大規模なモデルの学習と推論を高速化します。'),
  ('c4000000-4444-4444-4444-000000000004', 'AI開発においてGoogleが提唱する指針は？', '["秘密保持", "責任あるAI (Responsible AI) の原則", "技術至上主義", "利益優先"]'::jsonb, '責任あるAI (Responsible AI) の原則', '公平性、安全性、説明責任などを重視しています。'),
  ('c4000000-4444-4444-4444-000000000004', '「教師あり学習」の定義は？', '["データのみを与えて構造を見つける手法", "正解データを用いて学習させる手法", "学習を行わない", "報酬を与えて学習させる手法"]'::jsonb, '正解データを用いて学習させる手法', '分類や回帰などで一般的に使われます。'),
  ('c4000000-4444-4444-4444-000000000004', '「生成AI」が従来型のAIと異なる点は？', '["計算が遅い", "データの分析のみを行う", "管理が簡単", "新しいコンテンツを生成する"]'::jsonb, '新しいコンテンツを生成する', '既存のパターンから新しいアウトプットを作り出します。'),
  ('c4000000-4444-4444-4444-000000000004', '機械学習のプロセス「推論 (Inference)」とは？', '["学習済みモデルに新しいデータを与えて予測結果を得ること", "データを削除すること", "コードをデバッグすること", "モデルをゼロから作ること"]'::jsonb, '学習済みモデルに新しいデータを与えて予測結果を得ること', '本番環境で実際にAIが判断を下す工程です。'),
  ('c4000000-4444-4444-4444-000000000004', 'Vertex AI の「モデル チューニング」とは？', '["料金を安くすること", "既存の基盤モデルを自社の特定データで微調整し、精度を高めること", "モデルを削除すること", "モデルを1から作り直すこと"]'::jsonb, '既存の基盤モデルを自社の特定データで微調整し、精度を高めること', 'Fine-tuningとも呼ばれ、特定の用途に特化させます。'),
  ('c4000000-4444-4444-4444-000000000004', 'AIにおける「ハルシネーション」とは？', '["AIの速度が上がること", "AIが人間の顔を認識すること", "AIが計算を停止すること", "AIが事実に基づかない、もっともらしい嘘を出力すること"]'::jsonb, 'AIが事実に基づかない、もっともらしい嘘を出力すること', '生成AIを利用する際の大切な注意点です。'),
  ('c4000000-4444-4444-4444-000000000004', '生成AIの出力を、信頼できる外部データソース（自社ドキュメント等）に基づいて補完する技術は？', '["RAG (Retrieval-Augmented Generation)", "TPU", "AutoML", "Translation API"]'::jsonb, 'RAG (Retrieval-Augmented Generation)', '情報の鮮度と正確性を高めるために非常に有効な手法です。'),
  ('c4000000-4444-4444-4444-000000000004', '「翻訳 API」の機能は？', '["プログラムを解析する", "音声を録音する", "画像を表示する", "100以上の言語間でテキストを翻訳する"]'::jsonb, '100以上の言語間でテキストを翻訳する', 'Webサイトやアプリの多言語化を容易にします。'),
  ('c4000000-4444-4444-4444-000000000004', 'AIにおける「特徴量 (Feature)」とは？', '["予測に役立つ、データの特定の特性や属性", "ファイルの拡張子", "ユーザーの名前", "データの総量"]'::jsonb, '予測に役立つ、データの特定の特性や属性', '適切な特徴量を選ぶことがモデルの精度に大きく影響します。'),
  ('c4000000-4444-4444-4444-000000000004', '「MLOps」の目的は？', '["プログラマーを増やす", "AIを停止する", "計算コストを最大化する", "機械学習モデルの開発と運用を統合し、効率的にライフサイクルを管理する"]'::jsonb, '機械学習モデルの開発と運用を統合し、効率的にライフサイクルを管理する', 'DevOpsのML版であり、安定したAI運用に不可欠です。'),
  ('c4000000-4444-4444-4444-000000000004', 'Vertex AI Search の利点は？', '["自社の大量のドキュメントからGoogle検索のような精度で情報を探せる", "画像を検索する", "動画を編集する", "インターネット全体を検索する"]'::jsonb, '自社の大量のドキュメントからGoogle検索のような精度で情報を探せる', '社内のナレッジベース構築などに非常に強力です。'),
  ('c4000000-4444-4444-4444-000000000004', '「データ ラベリング」とは？', '["データを暗号化すること", "データをバックアップすること", "データを消去すること", "学習データに正解（犬、猫など）をタグ付けする作業"]'::jsonb, '学習データに正解をタグ付けする作業', '教師あり学習に不可欠な準備工程です。'),
  ('c4000000-4444-4444-4444-000000000004', 'AIの「バイアス」とは何を意味しますか？', '["精度が完璧なこと", "計算が速すぎること", "料金が安いこと", "学習データやアルゴリズムに偏りがあり、不公平な結果が出ること"]'::jsonb, '学習データやアルゴリズムに偏りがあり、不公平な結果が出ること', '責任あるAIにおいて回避すべき重要な課題です。'),
  ('c4000000-4444-4444-4444-000000000004', '「深層学習 (Deep Learning)」の特徴は？', '["層が一つしかない", "計算が不要である", "データが不要である", "多層のニューラルネットワークを用いて複雑なパターンを学習する"]'::jsonb, '多層のニューラルネットワークを用いて複雑なパターンを学習する', '画像認識や自然言語処理で高い成果を上げています。'),
  ('c4000000-4444-4444-4444-000000000004', '「転移学習 (Transfer Learning)」とは？', '["ある課題で学習した知識を、別の似た課題の学習に活用する", "データを移動させる", "学習を途中で止める", "モデルを捨てる"]'::jsonb, 'ある課題で学習した知識を、別の似た課題の学習に活用する', '少ないデータで高精度なモデルを短期間で作る手法です。'),
  ('c4000000-4444-4444-4444-000000000004', 'AIを利用した「予測保全」の例は？', '["機械を使わない", "壊れてから直す", "工場の機械の故障を事前に察知して修理する", "毎日機械を買い換える"]'::jsonb, '工場の機械の故障を事前に察知して修理する', 'ダウンタイムの削減とメンテナンスコストの最適化に寄与します。'),
  ('c4000000-4444-4444-4444-000000000004', 'AIによる「需要予測」が小売業にもたらすメリットは？', '["商品を無料で配る", "在庫不足や過剰在庫を防ぎ、収益を最大化する", "店を閉める", "価格を一律にする"]'::jsonb, '在庫不足や過剰在庫を防ぎ、収益を最大化する', 'データに基づいた効率的な店舗運営を可能にします。'),
  ('c4000000-4444-4444-4444-000000000004', '「プロンプト エンジニアリング」とは？', '["ハードウェアを修理すること", "データを暗号化すること", "生成AIから望ましい結果を引き出すための指示文を工夫すること", "プログラミングコードを書くこと"]'::jsonb, '生成AIから望ましい結果を引き出すための指示文を工夫すること', '生成AIの能力を最大限に引き出すための新しいスキルです。'),
  ('c4000000-4444-4444-4444-000000000004', 'Google Cloud の「AI Hub」の目的は？', '["サーバーを置く場所", "機械学習資産（ノートブックやパイプライン）を共有・管理する", "ロゴを作る場所", "AIを販売する場所"]'::jsonb, '機械学習資産を共有・管理する', 'チーム内でのAI資産の再利用を促進します。'),
  ('c4000000-4444-4444-4444-000000000004', '「コンピュータ ビジョン」の定義は？', '["映画を撮る技術", "絵を描く技術", "コンピュータの画面を直す技術", "コンピュータが画像や動画から情報を抽出・理解する技術"]'::jsonb, 'コンピュータが画像や動画から情報を抽出・理解する技術', '自動運転や検品、顔認証など広く応用されています。'),
  ('c4000000-4444-4444-4444-000000000004', '「強化学習」の説明は？', '["学習しない手法", "答えを教える手法", "データを分類する手法", "試行錯誤を通じて、報酬を最大化するように学習する手法"]'::jsonb, '試行錯誤を通じて、報酬を最大化するように学習する手法', '囲碁AIやロボットの制御などで使われます。'),
  ('c4000000-4444-4444-4444-000000000004', 'Vertex AI の「パイプライン」の利点は？', '["水を運ぶ", "データを削除する", "MLワークフローを自動化し、再利用や追跡を可能にする", "速度を制限する"]'::jsonb, 'MLワークフローを自動化し、再利用や追跡を可能にする', 'モデルのトレーニングからデプロイまでの流れを標準化します。'),
  ('c4000000-4444-4444-4444-000000000004', 'Google Cloud が提供する「AI Readiness」評価とは？', '["組織がAIを導入するための準備状況を診断すること", "AIの速度を測ること", "AIを捨てること", "AIの価格を決めること"]'::jsonb, '組織がAIを導入するための準備状況を診断すること', '技術、データ、人、プロセスの観点から評価します。');
INSERT INTO public.questions (category_id, content, options, answer, explanation)
VALUES 
  ('c5000000-5555-5555-5555-000000000005', '責任共有モデルの説明は？', '["インフラはGoogle、データはユーザーが担当", "ユーザーが物理サーバーを保守", "Googleが全て担当", "常に範囲は同じ"]'::jsonb, 'インフラはGoogle、データはユーザーが担当', '利用モデルによって範囲が変わります。'),
  ('c5000000-5555-5555-5555-000000000005', 'アクセス権限を「誰が・何に・何を」で管理するのは？', '["Cloud Armor", "IAM", "Identity-Aware Proxy", "Cloud Identity"]'::jsonb, 'IAM', '最小権限の原則に基づくアクセス制御です。'),
  ('c5000000-5555-5555-5555-000000000005', 'アイデンティティに基づくアクセス制御モデルは？', '["ゼロトラスト", "ファイアウォール", "境界防御", "VPN"]'::jsonb, 'ゼロトラスト', 'ネットワークの場所に関わらず安全性を確保します。'),
  ('c5000000-5555-5555-5555-000000000005', 'Google発の信頼性を高める運用手法は？', '["Waterfall", "Agile", "SRE", "DevOps"]'::jsonb, 'SRE', 'エンジニアリング手法を運用に適用します。'),
  ('c5000000-5555-5555-5555-000000000005', 'DDoS攻撃やWAF機能を提供するセキュリティは？', '["Cloud Firewall", "Cloud VPN", "Cloud Armor", "VPC"]'::jsonb, 'Cloud Armor', 'エッジで攻撃を遮断します。'),
  ('c5000000-5555-5555-5555-000000000005', '監視・ログ収集・分析を行う運用スイートは？', '["Identity Platform", "BigQuery", "Google Cloud Operations Suite", "Compute Engine"]'::jsonb, 'Google Cloud Operations Suite', 'Monitoring, Loggingなどを統合。'),
  ('c5000000-5555-5555-5555-000000000005', '暗号鍵の管理を中央で行うサービスは？', '["Cloud Armor", "Cloud IAM", "Secret Manager", "Cloud KMS"]'::jsonb, 'Cloud KMS', 'データの暗号化・復号に使用する鍵を管理します。'),
  ('c5000000-5555-5555-5555-000000000005', 'APIキーやパスワードなどの機密情報を安全に保存するのは？', '["Cloud Storage", "Cloud KMS", "Secret Manager", "Persistent Disk"]'::jsonb, 'Secret Manager', 'アプリから動的に情報を取得できます。'),
  ('c5000000-5555-5555-5555-000000000005', '脆弱性の検出や脅威を監視する統合ダッシュボードは？', '["Security Command Center", "Error Reporting", "Cloud Asset Inventory", "Cloud Trace"]'::jsonb, 'Security Command Center', 'プロジェクト全体の状況を可視化します。'),
  ('c5000000-5555-5555-5555-000000000005', '外部からのHTTPSトラフィックの認証を一元化するプロキシは？', '["Cloud Interconnect", "Identity-Aware Proxy", "Cloud VPN", "Cloud Load Balancing"]'::jsonb, 'Identity-Aware Proxy', 'VPNなしで内部アプリへのアクセスを制御。'),
  ('c5000000-5555-5555-5555-000000000005', '特定のサービス間のデータ移動を制限し、データ流出を防ぐのは？', '["VPC Service Controls", "VPC Peering", "Cloud NAT", "Shared VPC"]'::jsonb, 'VPC Service Controls', '境界を設けてデータを保護します。'),
  ('c5000000-5555-5555-5555-000000000005', '法規制要件に適合したリソース実行を保証するのは？', '["IAM Recommender", "Cloud KMS", "Resource Manager", "Assured Workloads"]'::jsonb, 'Assured Workloads', '政府機関や特定の業界の規制遵守を支援。'),
  ('c5000000-5555-5555-5555-000000000005', '不要な権限を持つユーザーを特定し、最小権限を提案するのは？', '["Cloud IAM", "Policy Troubleshooter", "Security Health Analytics", "IAM Recommender"]'::jsonb, 'IAM Recommender', '機械学習で適切な権限をリコメンドします。'),
  ('c5000000-5555-5555-5555-000000000005', 'データの「機密性」とは何を確保することですか？', '["データが複製されること", "常にアクセスできること", "アクセス権のない人がデータを見られないこと", "データが改ざんされないこと"]'::jsonb, 'アクセス権のない人がデータを見られないこと', '情報の漏洩を防ぐ特性です。'),
  ('c5000000-5555-5555-5555-000000000005', 'SREの指標「SLO」とは？', '["実際の稼働率の結果", "最低限保証する品質の契約", "エラーの総数", "目標とする信頼性のレベル"]'::jsonb, '目標とする信頼性のレベル', 'チームが目指すべき健全性指標です。'),
  ('c5000000-5555-5555-5555-000000000005', 'SREの指標「SLA」とは？', '["セキュリティガイドライン", "顧客へのサービス品質保証と返金等の契約", "チーム内部の目標", "開発速度の指標"]'::jsonb, '顧客へのサービス品質保証と返金等の契約', '法的な拘束力を持つ合意事項です。'),
  ('c5000000-5555-5555-5555-000000000005', '「エラーバジェット」の考え方は？', '["サーバーの購入予算", "セキュリティソフトの費用", "システムのバグ修正費用", "SLOを満たすために許容される不稼働時間"]'::jsonb, 'SLOを満たすために許容される不稼働時間', '信頼性と速度のバランスをとる仕組みです。'),
  ('c5000000-5555-5555-5555-000000000005', '保存されているデータ (Data at Rest) を保護する手法は？', '["暗号化", "削除", "バックアップのみ", "公開"]'::jsonb, '暗号化', 'Google Cloudではデフォルトで暗号化されます。'),
  ('c5000000-5555-5555-5555-000000000005', '転送中のデータ (Data in Transit) を保護するのは？', '["HTTP", "TLS/SSL (HTTPS)", "Telnet", "FTP"]'::jsonb, 'TLS/SSL (HTTPS)', '通信経路を暗号化して盗聴を防ぎます。'),
  ('c5000000-5555-5555-5555-000000000005', 'データセンターの物理セキュリティに対するGoogleの責任は？', '["ユーザーへの鍵貸与", "ユーザーによる警備", "アクセス監視、生体認証、ディスク破棄など", "管理の放棄"]'::jsonb, 'アクセス監視、生体認証、ディスク破棄など', 'インフラ全体の物理的保護をGoogleが行います。'),
  ('c5000000-5555-5555-5555-000000000005', 'IAM における「最小権限の原則」とは？', '["全員に管理者権限を与えること", "業務に必要な最小限の権限のみを付与すること", "ランダムに権限を与えること", "権限を全く与えないこと"]'::jsonb, '業務に必要な最小限の権限のみを付与すること', 'セキュリティリスクを最小限に抑えるための鉄則です。'),
  ('c5000000-5555-5555-5555-000000000005', 'IAM の「サービス アカウント」とは？', '["課金担当者のアカウント", "個人のメールアドレス", "サポート窓口のアカウント", "人間ではなく、アプリや仮想マシンが使用するアイデンティティ"]'::jsonb, '人間ではなく、アプリや仮想マシンが使用するアイデンティティ', 'システム間の認証を安全に行うために使用します。'),
  ('c5000000-5555-5555-5555-000000000005', '「Cloud Audit Logs」の目的は？', '["プログラムのミスを探す", "誰が、いつ、どこで、何をしたかの履歴を記録する", "メールを保存する", "料金を計算する"]'::jsonb, '誰が、いつ、どこで、何をしたかの履歴を記録する', 'コンプライアンスや不正アクセスの調査に不可欠です。'),
  ('c5000000-5555-5555-5555-000000000005', '「多要素認証 (MFA)」を導入する理由は？', '["パスワード盗難時でも、別の要素で不正アクセスを防ぐため", "パスワードを忘れないため", "画面を華やかにするため", "ログインを遅くするため"]'::jsonb, 'パスワード盗難時でも、別の要素で不正アクセスを防ぐため', 'セキュリティを飛躍的に高める重要な設定です。'),
  ('c5000000-5555-5555-5555-000000000005', 'SRE における「トイル (Toil)」とは何を指しますか？', '["手作業で反復的、かつ自動化可能な、ビジネス価値を直接生まない作業", "創造的な開発作業", "休暇", "最新技術の学習"]'::jsonb, '手作業で反復的、かつ自動化可能な、ビジネス価値を直接生まない作業', 'トイルを減らし、エンジニアリングに時間を割くのがSREの目標です。'),
  ('c5000000-5555-5555-5555-000000000005', '「ブルー/グリーン デプロイメント」の利点は？', '["古い環境を即座に消す", "新旧環境を並行させ、瞬時に切り替えることでダウンタイムとリスクを減らす", "開発者が2倍必要", "料金が安くなる"]'::jsonb, '新旧環境を並行させ、瞬時に切り替えることでダウンタイムとリスクを減らす', '問題発生時の切り戻し（ロールバック）も迅速に行えます。'),
  ('c5000000-5555-5555-5555-000000000005', '「カナリア デプロイメント」とは？', '["一部のユーザーにのみ新バージョンを先行公開し、安全性を確認する", "プログラムを鳥に例えること", "テストをしないこと", "全ユーザーを一気に更新する"]'::jsonb, '一部のユーザーにのみ新バージョンを先行公開し、安全性を確認する', 'リスクを最小限に抑えつつリリースを行う手法です。'),
  ('c5000000-5555-5555-5555-000000000005', '「完全性 (Integrity)」とは何を確保することですか？', '["データが最新であること", "データが改ざんされておらず、正確で信頼できること", "データが秘密であること", "データが常に利用できること"]'::jsonb, 'データが改ざんされておらず、正確で信頼できること', '情報セキュリティの三要素の一つです。'),
  ('c5000000-5555-5555-5555-000000000005', '「可用性 (Availability)」とは何を確保することですか？', '["料金が安いこと", "データが盗まれないこと", "データが正しいこと", "必要な時に、認可されたユーザーが常にサービスを利用できること"]'::jsonb, '必要な時に、認可されたユーザーが常にサービスを利用できること', 'システムの稼働率に関わる特性です。'),
  ('c5000000-5555-5555-5555-000000000005', 'Google Cloud の「データ暗号化」に関する正しい記述は？', '["暗号化は不可能である", "ユーザーが設定しないと暗号化されない", "有料オプションである", "デフォルトで保存時も転送時も暗号化されている"]'::jsonb, 'デフォルトで保存時も転送時も暗号化されている', 'Googleの堅牢なインフラ基盤が標準で提供する機能です。'),
  ('c5000000-5555-5555-5555-000000000005', '「カスタマー マネージド暗号鍵 (CMEK)」の利点は？', '["鍵をなくしても大丈夫になる", "Googleが鍵を完全に隠す", "ユーザー自身が暗号鍵のライフサイクルやアクセス権を制御できる", "料金が無料になる"]'::jsonb, 'ユーザー自身が暗号鍵のライフサイクルやアクセス権を制御できる', 'より高度な制御が必要な規制業界などで利用されます。'),
  ('c5000000-5555-5555-5555-000000000005', '「Cloud Trace」の目的は？', '["ログを表示する", "DBを監視する", "分散システムのアプリパフォーマンス（遅延）を分析する", "エラーをメールで送る"]'::jsonb, '分散システムのアプリパフォーマンスを分析する', 'マイクロサービス環境でのボトルネック特定に役立ちます。'),
  ('c5000000-5555-5555-5555-000000000005', '「Error Reporting」の機能は？', '["コードを修正する", "ログを消去する", "実行中のアプリで発生したクラッシュやエラーを集約して通知する", "サーバーを再起動する"]'::jsonb, '実行中のアプリで発生したクラッシュやエラーを集約して通知する', '修正が必要な問題をいち早く把握できます。'),
  ('c5000000-5555-5555-5555-000000000005', '「組織ポリシー サービス」の利点は？', '["個人のPCを管理する", "メールのパスワードを変える", "組織全体に対して、リソースの利用方法を一元的に制限・管理できる", "料金を支払う"]'::jsonb, '組織全体に対して、リソースの利用方法を一元的に制限・管理できる', '「特定のリージョン以外でのリソース作成を禁止する」などの制御が可能です。'),
  ('c5000000-5555-5555-5555-000000000005', '「BeyondCorp Enterprise」が実現するセキュリティは？', '["VPN不要で、あらゆる場所からセキュアなアクセスを可能にするゼロトラスト", "物理的な壁を作る", "ウイルス対策ソフトを配る", "ファイアウォールを2倍にする"]'::jsonb, 'VPN不要で、あらゆる場所からセキュアなアクセスを可能にするゼロトラスト', 'Googleが社内で実践しているセキュリティモデルを製品化したものです。'),
  ('c5000000-5555-5555-5555-000000000005', '「VPC ファイアウォール ルール」の役割は？', '["データを暗号化する", "ドメイン名を管理する", "VMへのトラフィック（通信）を許可または拒否する", "物理的なサーバーを冷やす"]'::jsonb, 'VMへのトラフィックを許可または拒否する', 'ネットワークレベルでのアクセス制御を行います。'),
  ('c5000000-5555-5555-5555-000000000005', '「Binary Authorization」の目的は？', '["パスワードを生成する", "信頼できるコンテナイメージのみがデプロイされるように制限する", "ファイルを圧縮する", "数値を数える"]'::jsonb, '信頼できるコンテナイメージのみがデプロイされるように制限する', 'サプライチェーンセキュリティを強化します。'),
  ('c5000000-5555-5555-5555-000000000005', '「ポストモーテム (Postmortem)」とは何を指しますか？', '["障害後に原因を分析し、再発防止策をまとめる「責めない」ドキュメント", "謝罪会見", "障害中のチャット", "お祝い会"]'::jsonb, '障害後に原因を分析し、再発防止策をまとめる「責めない」ドキュメント', '失敗から学び、システムの信頼性を向上させるための文化です。'),
  ('c5000000-5555-5555-5555-000000000005', '「ディザスタ リカバリ (DR)」の目的は？', '["新しいPCを買うこと", "サーバーを火災から守ること", "毎日バックアップを取ること", "大規模な災害時にシステムを迅速に復旧させる計画と準備"]'::jsonb, '大規模な災害時にシステムを迅速に復旧させる計画と準備', 'ビジネスの継続性 (BCP) を確保するために重要です。'),
  ('c5000000-5555-5555-5555-000000000005', '「Cloud Asset Inventory」の利点は？', '["サーバーを売る", "料金を下げる", "在庫を数える", "組織内のすべてのリソースの構成履歴を検索・監視できる"]'::jsonb, '組織内のすべてのリソースの構成履歴を検索・監視できる', 'ガバナンスとコンプライアンスの管理に役立ちます。');
